package com.repairconnect.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="reviews",uniqueConstraints=@UniqueConstraint(columnNames="booking_id")) public class Review { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false) private Booking booking; @ManyToOne(optional=false) private CustomerProfile customer; @ManyToOne(optional=false) private ProviderProfile provider; private int rating; @Column(length=1000) private String comment; private LocalDateTime createdAt=LocalDateTime.now(); public Review(){} public Review(Booking b,CustomerProfile c,ProviderProfile p,int r,String text){booking=b;customer=c;provider=p;rating=r;comment=text;} public Long getId(){return id;} public Booking getBooking(){return booking;} public ProviderProfile getProvider(){return provider;} public int getRating(){return rating;} public String getComment(){return comment;} public LocalDateTime getCreatedAt(){return createdAt;} }